#!/bin/bash
LINUX_FLAGS="-O3 -fPIE -pie -fsanitize=address,alignment,bool,bounds,enum,float-cast-overflow,float-divide-by-zero,integer-divide-by-zero,leak,nonnull-attribute,null,object-size,return,returns-nonnull-attribute,shift,signed-integer-overflow,undefined,unreachable,vla-bound,vptr"
INCLUDES="-I/mnt/c/users/azerty/my_project/my_libs -I/mnt/c/users/azerty/my_project/processor/helpers -I/mnt/c/users/azerty/my_project/processor/videotoasm -I/mnt/c/users/azerty/my_project/processor/processor -I/mnt/c/users/azerty/my_project/processor/assembly"
g++ assembly/assembly.cpp helpers/helpers.cpp ../my_libs/error_manage.cpp                       $LINUX_FLAGS -o outputexe/asm   -I/mnt/c/Users/Azerty/my_project/my_libs/ $INCLUDES
g++ processor/processor.cpp helpers/helpers.cpp stack/stack.cpp processor/processor_dump.cpp ../my_libs/error_manage.cpp processor/processor_commands.cpp    $LINUX_FLAGS -o outputexe/proc  -I/mnt/c/Users/Azerty/my_project/my_libs/ $INCLUDES
g++ videotoasm/videotoasm.cpp helpers/helpers.cpp  ../my_libs/error_manage.cpp                  $LINUX_FLAGS -o outputexe/video -I/mnt/c/Users/Azerty/my_project/my_libs/ $INCLUDES
g++ -I/mnt/c/users/azerty/my_project/my_libs -I/mnt/c/users/azerty/my_project/my_libs  programtoasm/programtoasm.cpp $LINUX_FLAGS -o outputexe/ProgramToAsm $INCLUDES